  <script>
    const toggle=document.querySelector('.menu-toggle');
    const links=document.querySelector('.nav-links');
    const languageButton=document.querySelector('#langToggle');
    function setLanguage(language){
      document.documentElement.lang=language;
      document.querySelectorAll('[data-bn][data-en]').forEach(element=>{element.textContent=element.dataset[language];});
      languageButton.textContent=language==='bn'?'EN':'বাংলা';
      languageButton.setAttribute('aria-label',language==='bn'?'Switch to English':'বাংলায় দেখুন');
      try{localStorage.setItem('nur-site-language',language);}catch(error){}
    }
    languageButton.addEventListener('click',()=>setLanguage(document.documentElement.lang==='bn'?'en':'bn'));
    let savedLanguage='bn';try{savedLanguage=localStorage.getItem('nur-site-language')||'bn';}catch(error){}setLanguage(savedLanguage);
    toggle.addEventListener('click',()=>{const open=links.classList.toggle('open');toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Close menu':'Open menu');});
    links.querySelectorAll('a').forEach(link=>link.addEventListener('click',()=>{links.classList.remove('open');toggle.setAttribute('aria-expanded','false');}));
  </script>
